// Frozen known-answer vectors for the Magnetar verifier core.
//
// One real FIPS 205 SLH-DSA-SHA2-128s key pair, one 32-byte message, and
// three signatures over that message that differ ONLY in the FIPS 205
// context octet string:
//
//	katSigHex        ctx = precompileCtx, "lux-evm-precompile-magnetar-v1"
//	katSigNoCtxHex   ctx = nil, i.e. plain FIPS 205 with no domain separation
//	katSigSlhdsaHex  ctx = "lux-evm-precompile-slhdsa-v1", slot 0x012203
//
// luxfi/crypto/slhdsa signs through circl's SignDeterministic, so a signature
// is a pure function of (sk, message, ctx). Freezing costs nothing in
// reproducibility and buys everything in strength: the round-trip tests mint a
// fresh key every run, so they still pass if the signer, the wire codec and
// the verifier are all uniformly wrong together. These bytes cannot move.
//
// The two reject vectors carry the cross-slot replay property. 0x012203
// (single-party SLH-DSA) and 0x012207 (Magnetar threshold SLH-DSA) run the
// SAME FIPS 205 verifier over the SAME parameter sets. The context string is
// the only thing keeping a signature minted for one slot out of the other. A
// verifier that dropped the context -- VerifySignature rather than
// VerifySignatureCtx -- would still accept every fresh signature a round-trip
// test minted for itself. It cannot accept these.
//
// Provenance: slhdsa.GenerateKey(crypto/rand, SHA2_128s), then SignCtx three
// times over msg = 00 01 02 .. 1f. Sizes are asserted against the mode table
// in TestKAT_VectorSizes rather than restated here.
const (
	katPKHex        = "ec882901a80f26acefb6490162f1abcf8edf6639307429821b427eda52a826b4"
	katMsgHex       = "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"
	katSigHex       = ""
	katSigNoCtxHex  = ""
	katSigSlhdsaHex = ""
)

// katMode is the parameter set the frozen vectors were minted under. SHA2_128s
// is the smallest FIPS 205 set, so the vector is 7856 signature bytes and
// verification is cheap enough to run over many tamper positions.
const katMode = ModeSHA2_128s

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	require.NoError(t, err)
	return b
}

// katParts decodes the accepted vector into independently mutable copies, so a
// caller may flip a bit without disturbing the next subtest.
func katParts(t *testing.T) (pk, msg, sig []byte) {
	t.Helper()
	return mustHex(t, katPKHex), mustHex(t, katMsgHex), mustHex(t, katSigHex)
}

// katFrame is the exact calldata frame the frozen vector encodes to.
func katFrame(t *testing.T) []byte {
	t.Helper()
	pk, msg, sig := katParts(t)
	return buildInput(katMode, pk, msg, sig)
}

// word is the 32-byte big-endian result the precompile returns. Comparing
// against the whole word also pins the 31 leading bytes to zero.
func word(v byte) []byte {
	w := make([]byte, 32)
	w[31] = v
	return w
}

// call invokes the precompile with exactly the gas RequiredGas asks for.
func call(t *testing.T, input []byte) ([]byte, error) {
	t.Helper()
	out, _, err := MagnetarVerifyPrecompile.Run(
		nil, common.Address{}, ContractMagnetarVerifyAddress,
		input, MagnetarVerifyPrecompile.RequiredGas(input), true,
	)
	return out, err
}

// TestKAT_VectorSizes pins the frozen vector against the precompile's own mode
// table AND against the sizes the library it dispatches into reports. If those
// two ever disagree, the pubKeyLen equality check admits a key the verifier
// then rejects, or a signature slice is cut at the wrong offset.
func TestKAT_VectorSizes(t *testing.T) {
	pk, msg, sig := katParts(t)

	pkSize, sigSize, _, m, err := getModeParams(katMode)
	require.NoError(t, err)

	require.Len(t, pk, pkSize)
	require.Len(t, sig, sigSize)
	require.Len(t, msg, 32)
	require.Len(t, mustHex(t, katSigNoCtxHex), sigSize)
	require.Len(t, mustHex(t, katSigSlhdsaHex), sigSize)

	require.Equal(t, slhdsa.GetPublicKeySize(m), pkSize,
		"precompile pubkey size disagrees with luxfi/crypto/slhdsa")
	require.Equal(t, slhdsa.GetSignatureSize(m), sigSize,
		"precompile signature size disagrees with luxfi/crypto/slhdsa")

	// The frame the vector encodes to is exactly the offsets Run computes.
	require.Len(t, katFrame(t),
		ModeByte+PubKeyLenSize+pkSize+MessageLenSize+len(msg)+sigSize)
}

// TestKAT_Accept is the positive known answer: the frozen vector MUST verify
// true through the precompile, and the result MUST be the canonical ABI word.
func TestKAT_Accept(t *testing.T) {
	out, err := call(t, katFrame(t))
	require.NoError(t, err)
	require.Equal(t, word(1), out, "frozen KAT vector must verify true at slot 0x012207")
}

// TestKAT_DomainSeparation is the cross-slot replay refusal. Both reject
// vectors are genuine FIPS 205 signatures over the same key and the same
// message -- the subtest proves that first, so the refusal cannot be blamed on
// junk bytes. They differ from the accepted vector only in the context octet
// string, and the precompile MUST refuse them.
func TestKAT_DomainSeparation(t *testing.T) {
	pk, msg, sig := katParts(t)
	pub, err := slhdsa.PublicKeyFromBytes(pk, slhdsa.SHA2_128s)
	require.NoError(t, err)

	for _, tc := range []struct {
		name string
		hex  string
		ctx  []byte
	}{
		{"plain FIPS 205, empty context", katSigNoCtxHex, nil},
		{"single-party SLH-DSA slot 0x012203", katSigSlhdsaHex, []byte("lux-evm-precompile-slhdsa-v1")},
	} {
		t.Run(tc.name, func(t *testing.T) {
			other := mustHex(t, tc.hex)
			require.NotEqual(t, sig, other,
				"vector is identical to the magnetar-context signature; the test would be vacuous")
			require.True(t, pub.VerifySignatureCtx(msg, other, tc.ctx),
				"vector is not a genuine signature under its own context; the test would be vacuous")

			out, err := call(t, buildInput(katMode, pk, msg, other))
			require.NoError(t, err)
			require.Equal(t, word(0), out,
				"a signature minted under a different context must not verify at slot 0x012207")
		})
	}
}

// TestKAT_TamperSignature sweeps single-bit flips across the WOTS+, FORS and
// Merkle-authentication-path regions of the frozen signature. Every one MUST
// reject, and none may error -- an invalid signature is a false verdict, not a
// malformed frame.
func TestKAT_TamperSignature(t *testing.T) {
	pk, msg, _ := katParts(t)
	sigSize := len(mustHex(t, katSigHex))
	for _, pos := range []int{0, 1, 31, 100, 3000, sigSize / 2, sigSize - 2, sigSize - 1} {
		for _, bit := range []byte{0x01, 0x80} {
			_, _, sig := katParts(t)
			sig[pos] ^= bit
			out, err := call(t, buildInput(katMode, pk, msg, sig))
			require.NoError(t, err, "pos=%d bit=0x%02x", pos, bit)
			require.Equal(t, word(0), out,
				"single-bit signature tamper at pos=%d bit=0x%02x must reject", pos, bit)
		}
	}
}

// TestKAT_TamperPublicKey flips single bits in the FIPS 205 public key, which
// is seed || root. A flip in the root breaks the Merkle check; a flip in the
// seed changes every tweakable-hash address. Both MUST reject.
func TestKAT_TamperPublicKey(t *testing.T) {
	_, msg, sig := katParts(t)
	pkSize := len(mustHex(t, katPKHex))
	for _, pos := range []int{0, 1, pkSize/2 - 1, pkSize / 2, pkSize - 1} {
		pk, _, _ := katParts(t)
		pk[pos] ^= 0x01
		out, err := call(t, buildInput(katMode, pk, msg, sig))
		require.NoError(t, err, "pos=%d", pos)
		require.Equal(t, word(0), out, "single-bit pubkey tamper at pos=%d must reject", pos)
	}
}

// TestKAT_TamperMessage is the message binding: the frozen signature MUST NOT
// verify against any message but the one it was minted over, including a
// message that is merely one byte longer or shorter.
func TestKAT_TamperMessage(t *testing.T) {
	pk, _, sig := katParts(t)

	for _, pos := range []int{0, 15, 31} {
		_, msg, _ := katParts(t)
		msg[pos] ^= 0x01
		out, err := call(t, buildInput(katMode, pk, msg, sig))
		require.NoError(t, err, "pos=%d", pos)
		require.Equal(t, word(0), out, "single-bit message tamper at pos=%d must reject", pos)
	}

	_, msg, _ := katParts(t)
	for _, alt := range [][]byte{
		msg[:len(msg)-1],
		append(append([]byte(nil), msg...), 0x00),
		{},
	} {
		out, err := call(t, buildInput(katMode, pk, alt, sig))
		require.NoError(t, err, "len=%d", len(alt))
		require.Equal(t, word(0), out, "message of length %d must reject", len(alt))
	}
}

// TestKAT_ZeroPublicKey feeds an all-zero public key of the correct length. A
// FIPS 205 public key is an unstructured seed || root pair, so decoding
// succeeds and the refusal has to come from the verifier itself.
func TestKAT_ZeroPublicKey(t *testing.T) {
	pk, msg, sig := katParts(t)
	zero := make([]byte, len(pk))

	_, err := slhdsa.PublicKeyFromBytes(zero, slhdsa.SHA2_128s)
	require.NoError(t, err, "an all-zero pubkey decodes; the refusal must come from the verifier")

	out, err := call(t, buildInput(katMode, zero, msg, sig))
	require.NoError(t, err)
	require.Equal(t, word(0), out, "all-zero public key must not verify")
}

// TestKAT_CrossParameterSet is parameter-set confusion. SHA2-128s and
// SHAKE-128s have byte-identical wire sizes -- 32-byte key, 7856-byte
// signature -- so the mode byte is the ONLY thing that routes the frame to the
// right hash family. A SHA2 vector submitted as SHAKE reaches the verifier and
// MUST come back false. Every other parameter set differs in at least one
// size, so those frames are refused by the length checks before the verifier
// ever runs.
func TestKAT_CrossParameterSet(t *testing.T) {
	pk, msg, sig := katParts(t)

	t.Run("same sizes, wrong hash family", func(t *testing.T) {
		pkSize, sigSize, _, _, err := getModeParams(ModeSHAKE_128s)
		require.NoError(t, err)
		require.Equal(t, len(pk), pkSize, "the confusion test needs identical wire sizes")
		require.Equal(t, len(sig), sigSize, "the confusion test needs identical wire sizes")

		out, err := call(t, buildInput(ModeSHAKE_128s, pk, msg, sig))
		require.NoError(t, err)
		require.Equal(t, word(0), out,
			"a SHA2-128s signature must not verify as SHAKE-128s")
	})

	for _, mode := range []uint8{
		ModeSHA2_128f, ModeSHA2_192s, ModeSHA2_192f, ModeSHA2_256s, ModeSHA2_256f,
		ModeSHAKE_128f, ModeSHAKE_192s, ModeSHAKE_192f, ModeSHAKE_256s, ModeSHAKE_256f,
	} {
		t.Run(ModeName(mode), func(t *testing.T) {
			out, err := call(t, buildInput(mode, pk, msg, sig))
			require.Error(t, err, "mismatched sizes must be refused, not verified")
			require.ErrorIs(t, err, ErrInvalidInputLength)
			require.Nil(t, out)
		})
	}
}
